#include <string>
#include <cstring>
using namespace std;

string s;
long long memo[11][1024][2];

long long dfs(int pos, int mask, bool tight) {
    if (pos == (int)s.size())
        return mask != 0;

    if (!tight && memo[pos][mask][0] != -1)
        return memo[pos][mask][0];

    int limit = tight ? s[pos] - '0' : 9;
    long long result = 0;

    for (int digit = 0; digit <= limit; ++digit) {
        int newMask = mask;

        if (mask != 0 || digit != 0)
            newMask |= 1 << digit;

        if (__builtin_popcount((unsigned)newMask) <= 2)
            result += dfs(pos + 1, newMask, tight && digit == limit);
    }

    if (!tight)
        memo[pos][mask][0] = result;

    return result;
}

