#include <iostream>
#include <string>
#include <cstring>
using namespace std;

string s;
long long memo[11][1024];

long long solve(int pos, int mask, bool tight) {
    if (pos == (int)s.size())
        return mask != 0;

    if (!tight && memo[pos][mask] != -1)
        return memo[pos][mask];

    int limit = tight ? s[pos] - '0' : 9;
    long long result = 0;

    for (int digit = 0; digit <= limit; ++digit) {
        int newMask = mask;

        if (mask == 0 && digit == 0) {
            newMask = 0;
        } else {
            newMask |= 1 << digit;
            if (__builtin_popcount((unsigned)newMask) > 2)
                continue;
        }

        result += solve(pos + 1, newMask, tight && digit == limit);
    }

    if (!tight)
        memo[pos][mask] = result;

    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> s;
    memset(memo, -1, sizeof(memo));

    cout << solve(0, 0, true) << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

string s;
long long memo[11][1024][2];
bool seen[11][1024][2];

long long dfs(int pos, int mask, bool started, bool tight) {
    if (pos == (int)s.size())
        return started ? 1 : 0;

    if (!tight && seen[pos][mask][started])
        return memo[pos][mask][started];

    int limit = tight ? s[pos] - '0' : 9;
    long long result = 0;

    for (int digit = 0; digit <= limit; ++digit) {
        bool nextTight = tight && (digit == limit);
        if (!started && digit == 0) {
            result += dfs(pos + 1, mask, false, nextTight);
        } else {
            int nextMask = mask | (1 << digit);
            if (__builtin_popcount((unsigned)nextMask) <= 2)
                result += dfs(pos + 1, nextMask, true, nextTight);
        }
    }

    if (!tight) {
        seen[pos][mask][started] = true;
        memo[pos][mask][started] = result;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> s;
    cout << dfs(0, 0, false, true) << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string n;
    cin >> n;

    long long dp[2][1024] = {};
    dp[1][0] = 1;

    for (char c : n) {
        long long next[2][1024] = {};
        int bound = c - '0';

        for (int tight = 0; tight <= 1; ++tight) {
            for (int mask = 0; mask < 1024; ++mask) {
                if (dp[tight][mask] == 0) continue;

                int limit = tight ? bound : 9;
                for (int digit = 0; digit <= limit; ++digit) {
                    int newMask = mask;
                    if (mask != 0 || digit != 0)
                        newMask |= 1 << digit;

                    if (__builtin_popcount(newMask) > 2) continue;

                    int newTight = tight && (digit == bound);
                    next[newTight][newMask] += dp[tight][mask];
                }
            }
        }

        memcpy(dp, next, sizeof(dp));
    }

    long long answer = 0;
    for (int tight = 0; tight <= 1; ++tight)
        for (int mask = 1; mask < 1024; ++mask)
            answer += dp[tight][mask];

    cout << answer << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

string s;
long long memo[11][2][2][1024];

long long dfs(int pos, bool tight, bool started, int mask) {
    if (pos == (int)s.size()) return started;

    long long &res = memo[pos][tight][started][mask];
    if (res != -1) return res;
    res = 0;

    int limit = tight ? s[pos] - '0' : 9;
    for (int digit = 0; digit <= limit; ++digit) {
        bool nextTight = tight && (digit == limit);

        if (!started && digit == 0) {
            res += dfs(pos + 1, nextTight, false, 0);
        } else {
            int nextMask = mask | (1 << digit);
            if (__builtin_popcount((unsigned)nextMask) <= 2)
                res += dfs(pos + 1, nextTight, true, nextMask);
        }
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> s;
    memset(memo, -1, sizeof(memo));
    cout << dfs(0, true, false, 0) << '\n';

    return 0;
}
